INSERT INTO cfg.rule (id, indicator_id, low, high, baseline_direction, baseline_deviations, title, explanation, action, threshold_source) VALUES
  (1, 'glucose', 65.0, 99.0, NULL, NULL, 'Glucose out of range', 'Your blood glucose is outside the normal range of 65 to 99 mg/dL. This can be a sign of abnormal glucose regulation.', 'Ask for a metabolic assessment.', 'Normal range given for glucose in the Inspiration4 metabolic panel file (NASA OSDR, OSD-575).'),
  (2, 'resting_heart_rate', NULL, 100.0, NULL, NULL, 'Resting heart rate high', 'Your resting heart rate is above 100 bpm. At rest, this can point to dehydration, infection, stress or a cardiovascular problem.', 'Check your hydration and how you feel, and ask for a cardiovascular assessment.', 'American Heart Association definition of tachycardia: a resting heart rate above 100 bpm. General adult reference on Earth, not a spaceflight limit.'),
  (3, 'sleep_duration', 420.0, NULL, NULL, NULL, 'Short night', 'You slept less than 7 hours (420 minutes). Too little sleep, night after night, lowers attention and mood.', 'Adjust your schedule to protect tonight''s sleep and review what kept you awake.', 'American Academy of Sleep Medicine and Sleep Research Society consensus for adults, 2015: 7 or more hours per night. https://doi.org/10.5664/jcsm.4758. General adult reference on Earth, not a spaceflight limit.'),
  (4, 'mood_sad_days_14', NULL, 7.0, NULL, NULL, 'Sad on most of the last 14 days', 'You chose Sad on more than half of the last 14 days. It is not a diagnosis. It is a reason to talk about it.', 'Bring it up in your next private psychological conference.', 'PHQ-2 depression screening (Kroenke, Spitzer and Williams, Medical Care, 2003) asks about the last 2 weeks, and "more than half the days" is the answer that starts to count. This is an adaptation, not a validated screening: each questionnaire has two questions and the check-in covers one. To confirm with the medical reviewer.'),
  (5, 'mood_tense_days_14', NULL, 7.0, NULL, NULL, 'Tense or anxious on most of the last 14 days', 'You chose Tense or anxious on more than half of the last 14 days. It is not a diagnosis. It is a reason to talk about it.', 'Bring it up in your next private psychological conference.', 'GAD-2 anxiety screening (Kroenke et al., Annals of Internal Medicine, 2007) asks about the last 2 weeks, and "more than half the days" is the answer that starts to count. This is an adaptation, not a validated screening: each questionnaire has two questions and the check-in covers one. To confirm with the medical reviewer.'),
  (6, 'sodium', 135.0, 146.0, NULL, NULL, 'Sodium out of range', 'Your blood sodium is outside the normal range of 135 to 146 mmol/L. This is an electrolyte imbalance.', 'Repeat the test and ask for a clinical review.', 'Normal range given for sodium in the Inspiration4 metabolic panel file (NASA OSDR, OSD-575).'),
  (7, 'potassium', 3.5, 5.3, NULL, NULL, 'Potassium out of range', 'Your blood potassium is outside the normal range of 3.5 to 5.3 mmol/L. This is an electrolyte imbalance.', 'Repeat the test and ask for a clinical review.', 'Normal range given for potassium in the Inspiration4 metabolic panel file (NASA OSDR, OSD-575).'),
  (8, 'chloride', 98.0, 110.0, NULL, NULL, 'Chloride out of range', 'Your blood chloride is outside the normal range of 98 to 110 mmol/L. This is an electrolyte imbalance.', 'Repeat the test and ask for a clinical review.', 'Normal range given for chloride in the Inspiration4 metabolic panel file (NASA OSDR, OSD-575).'),
  (9, 'urea_nitrogen', 7.0, 25.0, NULL, NULL, 'Urea nitrogen out of range', 'Your blood urea nitrogen is outside the normal range of 7 to 25 mg/dL. This can be a sign of a change in kidney function.', 'Ask for a renal assessment.', 'Normal range given for urea nitrogen (BUN) in the Inspiration4 metabolic panel file (NASA OSDR, OSD-575).'),
  (10, 'egfr', 60.0, NULL, NULL, NULL, 'Kidney filtration rate low', 'Your estimated kidney filtration rate (eGFR) is below 60 mL/min/1.73 m². This can be a sign that the kidneys are working less well.', 'Ask for a renal assessment.', 'Lower limit given for eGFR in the Inspiration4 metabolic panel file (NASA OSDR, OSD-575). The file gives no upper limit.'),
  (11, 'albumin', 3.6, 5.1, NULL, NULL, 'Albumin out of range', 'Your blood albumin is outside the normal range of 3.6 to 5.1 g/dL. This can be a sign of a nutritional deficiency.', 'Ask for a targeted nutritional assessment.', 'Normal range given for albumin in the Inspiration4 metabolic panel file (NASA OSDR, OSD-575).'),
  (12, 'creatinine', 0.5, 1.35, NULL, NULL, 'Creatinine out of range', 'Your creatinine is outside the normal range of 0.5 to 1.35 mg/dL. This can be a sign of a change in kidney function.', 'Ask for a renal assessment.', 'Widest of the normal ranges given for creatinine in the Inspiration4 metabolic panel file (NASA OSDR, OSD-575). The file gives a different range by astronaut and draw.'),
  (13, 'calcium', 8.6, 10.4, NULL, NULL, 'Calcium out of range', 'Your blood calcium is outside the normal range of 8.6 to 10.4 mg/dL.', 'Repeat the test and ask for a clinical review.', 'Widest of the normal ranges given for calcium in the Inspiration4 metabolic panel file (NASA OSDR, OSD-575). The file gives a different range by astronaut and draw.'),
  (14, 'white_blood_cells', 3.8, 10.8, NULL, NULL, 'White blood cells out of range', 'Your white blood cell count is outside the normal range of 3.8 to 10.8 thousand/µL. This can be a sign of infection or of a weaker immune system.', 'Repeat the test and ask for a clinical review.', 'Normal range given in the Inspiration4 blood count file (NASA OSDR, OSD-569).'),
  (15, 'lymphocytes', 850.0, 3900.0, NULL, NULL, 'Lymphocytes out of range', 'Your lymphocyte count is outside the normal range of 850 to 3900 cells/µL. A low count can be a sign of immune suppression.', 'Repeat the test.', 'Normal range given in the Inspiration4 blood count file (NASA OSDR, OSD-569).'),
  (16, 'hemoglobin', 11.7, 17.1, NULL, NULL, 'Haemoglobin out of range', 'Your haemoglobin is outside the normal range of 11.7 to 17.1 g/dL. This can be a sign of a nutritional deficiency.', 'Ask for a targeted nutritional assessment.', 'Widest of the normal ranges given for haemoglobin in the Inspiration4 blood count file (NASA OSDR, OSD-569). The file gives a different range by astronaut and draw.'),
  (17, 'vo2_max', 32.9, NULL, NULL, NULL, 'Cardiovascular fitness below the NASA limit', 'Your VO2 max is below 32.9 mL/kg/min, the minimum NASA sets during a mission with spacewalks in microgravity.', 'Review your exercise plan and your tolerance to effort.', 'NASA-STD-3001, Volume 1, requirement V1 4001: in-mission VO2 max at or above 32.9 mL/kg/min. https://www.nasa.gov/wp-content/uploads/2023/12/ochmo-tb-031-exercise-overview.pdf. The value shown is an estimate by the watch, not an exercise test.'),
  (18, 'resting_heart_rate', NULL, NULL, 'above', 3.0, 'Resting heart rate above your usual', 'Your resting heart rate is well above your own usual value of the last 4 weeks. A rise like this can point to dehydration, infection, stress or a cardiovascular problem, even when the value is normal for other people.', 'Check your hydration and how you feel, and measure it again tomorrow.', 'Your personal baseline: the median of your own readings of the last 28 days. The alert comes when a reading is more than 3 deviations above it, where a deviation is the median distance of those readings to their median, times 1.4826 (the Hampel identifier for outliers). It needs at least 14 readings. The 3 is our choice, not a medical limit.'),
  (19, 'skin_temperature', NULL, NULL, 'above', 3.0, 'Skin temperature above your usual', 'Your skin temperature during the night is well above your own usual value of the last 4 weeks. Together with symptoms, this can be an early sign of infection.', 'Check how you feel. If you have symptoms, start the infection assessment.', 'Your personal baseline: the median of your own readings of the last 28 days. The alert comes when a reading is more than 3 deviations above it, where a deviation is the median distance of those readings to their median, times 1.4826 (the Hampel identifier for outliers). It needs at least 14 readings. The 3 is our choice, not a medical limit.'),
  (20, 'heart_rate_variability', NULL, NULL, 'below', 3.0, 'Heart rate variability below your usual', 'Your heart rate variability is well below your own usual value of the last 4 weeks. A drop like this is a sign of physical stress: poor sleep, a hard effort or the start of an illness.', 'Protect tonight''s sleep, lower today''s effort if you can, and watch how it goes tomorrow.', 'Your personal baseline: the median of your own readings of the last 28 days. The alert comes when a reading is more than 3 deviations below it, where a deviation is the median distance of those readings to their median, times 1.4826 (the Hampel identifier for outliers). It needs at least 14 readings. The 3 is our choice, not a medical limit.'),
  (21, 'spo2', NULL, NULL, 'below', 3.0, 'Blood oxygen below your usual', 'Your blood oxygen is well below your own usual value of the last 4 weeks. A fall from your baseline is a reason to look at breathing and circulation.', 'Repeat the measurement. If it stays low, ask for a respiratory and cardiovascular assessment.', 'Your personal baseline: the median of your own readings of the last 28 days. The alert comes when a reading is more than 3 deviations below it, where a deviation is the median distance of those readings to their median, times 1.4826 (the Hampel identifier for outliers). It needs at least 14 readings. The 3 is our choice, not a medical limit.'),
  (22, 'stress_score', NULL, NULL, 'below', 3.0, 'Stress score below your usual', 'Your stress score is well below your own usual value of the last 4 weeks. On this score a lower number means more signs of physical stress.', 'Use a stress management routine today and check the score again tomorrow.', 'Your personal baseline: the median of your own readings of the last 28 days. The alert comes when a reading is more than 3 deviations below it, where a deviation is the median distance of those readings to their median, times 1.4826 (the Hampel identifier for outliers). It needs at least 14 readings. The 3 is our choice, not a medical limit.');
